     <a class="skip-link" href="#maincontent">Skip to main content</a>

     <div class="shell">
       <header>
         <div class="hero">
           <p class="eyebrow">Cat care essentials</p>
           <h1>Frequently asked questions about cats</h1>
           <p class="intro">
