422.     <script>
423.       const createDisclosureItem = (element) => {
424.         const button = element.querySelector("[data-disclosure-button]");
425.         const details = element.querySelector(".details");
426. 
427.         const setExpanded = (expanded) => {
428.           button.setAttribute("aria-expanded", String(expanded));
429.           details.hidden = !expanded;
430.         };
431. 
432.         const onToggle = () => {
433.           const expanded = button.getAttribute("aria-expanded") === "true";
434.           setExpanded(!expanded);
435.         };
436. 
437.         const onKeydown = (event) => {
438.           if (event.key === "Escape" && button.getAttribute("aria-expanded") === "true") {
439.             setExpanded(false);
440.             button.focus();
441.           }
442.         };
443. 
444.         return {
445.           mount() {
446.             setExpanded(false);
447.             button.addEventListener("click", onToggle);
448.             button.addEventListener("keydown", onKeydown);
449.           },
450.         };
451.       };
452. 
453.       const createFAQPage = (root) => {
454.         const items = Array.from(root.querySelectorAll(".example")).map(createDisclosureItem);
455. 
456.         return {
457.           mount() {
458.             items.forEach((item) => item.mount());
459.           },
460.         };
461.       };
462. 
463.       const root = document.querySelector("[data-faq-root]");
464.       const faqPage = createFAQPage(root);
