                   aria-expanded="true"
                   aria-controls="answer-play"
                 >
                   <span class="question-text">How much playtime does a healthy cat need?</span>
                   <svg class="chevron" viewBox="0 0 24 24" aria-hidden="true">
                     <path
                       d="M6 9.75 12 15.25 18 9.75"
                       fill="none"
                       stroke="currentColor"
                       stroke-linecap="round"
                       stroke-linejoin="round"
                       stroke-width="2"
                     />
                   </svg>
                 </button>
               </h3>
               <div class="details" id="answer-play">
                 <p>
                   Most cats benefit from <strong>two or three short play sessions</strong>
                   each day. Wand toys, puzzle feeders, and climbing spaces give them both
                   mental and physical stimulation.
                 </p>
                 <ul>
                   <li>Keep sessions brief and energetic.</li>
                   <li>Let the cat "catch" the toy at the end.</li>
                   <li>Match toy size and speed to the cat's age and mobility.</li>
                 </ul>
               </div>
             </div>
           </div>
         </section>
       </main>

       <footer>
         Built as a polished, keyboard-friendly disclosure FAQ with all answers collapsed
         by default when scripting is available.
       </footer>
     </div>

     <script>
       const createDisclosureItem = (element) => {
         const button = element.querySelector("[data-disclosure-button]");
         const details = element.querySelector(".details");

         const setExpanded = (expanded) => {
           button.setAttribute("aria-expanded", String(expanded));
           details.hidden = !expanded;
         };

         const onToggle = () => {
           const expanded = button.getAttribute("aria-expanded") === "true";
           setExpanded(!expanded);
         };

         const onKeydown = (event) => {
           if (event.key === "Escape" && button.getAttribute("aria-expanded") === "true") {
             setExpanded(false);
             button.focus();
           }
         };

         return {
           mount() {
             setExpanded(false);
             button.addEventListener("click", onToggle);
             button.addEventListener("keydown", onKeydown);
           },
         };
       };

       const createFAQPage = (root) => {
         const items = Array.from(root.querySelectorAll(".example")).map(createDisclosureItem);

         return {
           mount() {
             items.forEach((item) => item.mount());
           },
         };
       };

       const root = document.querySelector("[data-faq-root]");
       const faqPage = createFAQPage(root);
       faqPage.mount();
     </script>
   </body>
 </html>

')
